"""
消息分类器 — 判断用户消息应该路由到哪个脑区。

分类策略（两层）：
1. 关键词匹配 — 快速、免费、可离线
2. Claude API — 准确、理解上下文（如果配置了 API key）
"""
import re
import json
import logging
from enum import Enum
from datetime import datetime

from .config import (
    CATEGORY_PATTERNS, QUERY_PATTERNS, CHAT_PATTERNS,
    CLAUDE_API_KEY, CLAUDE_MODEL, CLAUDE_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")


class Category(Enum):
    QUERY = "QUERY"           # 查知识/提问
    TASK = "TASK"             # 要做的任务
    DECISION = "DECISION"     # 做出的判断/决策
    INSPIRATION = "INSPIRATION"  # 碎片灵感
    KNOWLEDGE = "KNOWLEDGE"   # 值得保存的知识/洞察
    MEETING = "MEETING"       # 会议/对话记录
    TODO = "TODO"             # 待办提醒
    CHAT = "CHAT"             # 闲聊，不存档


class Classification:
    """一条消息的分类结果"""
    def __init__(self, category: Category, title: str = "",
                 summary: str = "", confidence: float = 0.5,
                 target_subfolder: str = ""):
        self.category = category
        self.title = title
        self.summary = summary
        self.confidence = confidence
        self.target_subfolder = target_subfolder
        self.timestamp = datetime.now()

    def __repr__(self):
        return f"Classification({self.category.value}, '{self.title}', conf={self.confidence:.0%})"


def classify(text: str) -> Classification:
    """分类一条消息。先尝试关键词，关键词不确定时用 Claude。"""
    text = text.strip()
    if not text:
        return Classification(Category.CHAT, confidence=1.0)

    # 第一层：关键词匹配
    result = _keyword_classify(text)
    if result.confidence >= 0.7:
        return result

    # 第二层：Claude API（如果可用）
    if CLAUDE_API_KEY:
        try:
            return _claude_classify(text)
        except Exception as e:
            logger.warning(f"Claude 分类失败，回退到关键词: {e}")

    return result


def _keyword_classify(text: str) -> Classification:
    """基于关键词和正则的分类。"""

    # 先检查是否明确是闲聊
    for pattern in CHAT_PATTERNS:
        if re.search(pattern, text):
            return Classification(Category.CHAT, confidence=0.9)

    # 检查是否是查询
    for pattern in QUERY_PATTERNS:
        if re.search(pattern, text):
            return Classification(
                Category.QUERY,
                title=f"查询: {text[:30]}",
                summary=text,
                confidence=0.8,
            )

    # 匹配各类操作模式
    best_score = 0
    best_category = None

    for cat_name, patterns in CATEGORY_PATTERNS.items():
        score = 0
        for pattern in patterns:
            if re.search(pattern, text):
                score += 1
        if score > best_score:
            best_score = score
            best_category = Category[cat_name]

    if best_score >= 2:
        confidence = min(0.9, 0.4 + best_score * 0.2)
        title = _extract_title(text, best_category)
        return Classification(best_category, title=title, summary=text,
                              confidence=confidence)

    if best_score >= 1:
        title = _extract_title(text, best_category)
        return Classification(best_category, title=title, summary=text,
                              confidence=0.5)

    # 默认：如果文本较长，可能是灵感；如果短，可能是闲聊
    if len(text) > 30:
        return Classification(
            Category.INSPIRATION,
            title=text[:30],
            summary=text,
            confidence=0.3,
        )
    return Classification(Category.CHAT, confidence=0.3)


def _extract_title(text: str, category: Category) -> str:
    """从文本中提取简短标题。"""
    # 去掉命令前缀
    clean = re.sub(r'^[#/]\w+\s+', '', text).strip()
    # 取第一句话或前 30 字
    sentences = re.split(r'[。！？\n]', clean)
    first = sentences[0].strip() if sentences else clean
    if len(first) > 30:
        first = first[:30] + "…"
    return first


def _claude_classify(text: str) -> Classification:
    """使用 Claude API 进行智能分类。"""
    import anthropic

    client = anthropic.Anthropic(api_key=CLAUDE_API_KEY)

    categories_desc = "\n".join([
        "QUERY - 查知识/提问",
        "TASK - 要做的任务/项目",
        "DECISION - 做出的判断/选择",
        "INSPIRATION - 碎片灵感/随想",
        "KNOWLEDGE - 值得保存的知识/洞察",
        "MEETING - 会议/访谈/对话记录",
        "TODO - 待办提醒",
        "CHAT - 闲聊/测试，不需要存档",
    ])

    prompt = f"""分析这条消息，判断它属于哪一类。

消息内容：
---
{text}
---

可选类别：
{categories_desc}

请返回 JSON 格式：
{{"category": "分类名", "title": "简短标题(≤20字)", "summary": "一句话摘要(≤50字)", "confidence": 0.9, "reason": "判断依据"}}

注意：
- 如果消息包含问号或明显在提问 → QUERY
- 如果提到"要做""准备做""计划" → TASK
- 如果是随想的碎片灵感 → INSPIRATION
- 如果是学到的新知识、方法论 → KNOWLEDGE
- 如果只是确认/测试/闲聊 → CHAT
- title 和 summary 用中文
- 只返回 JSON，不要其他内容"""

    response = client.messages.create(
        model=CLAUDE_MODEL,
        max_tokens=CLAUDE_MAX_TOKENS,
        messages=[{"role": "user", "content": prompt}],
    )

    result_text = response.content[0].text.strip()
    # 清理可能的 markdown 代码块标记
    result_text = re.sub(r'^```(?:json)?\s*', '', result_text)
    result_text = re.sub(r'\s*```$', '', result_text)

    try:
        data = json.loads(result_text)
    except json.JSONDecodeError:
        logger.warning(f"Claude 返回非 JSON: {result_text[:100]}")
        return _keyword_classify(text)

    try:
        category = Category[data["category"]]
    except KeyError:
        category = Category.INSPIRATION

    return Classification(
        category=category,
        title=data.get("title", text[:20]),
        summary=data.get("summary", text[:50]),
        confidence=data.get("confidence", 0.7),
    )

"""
Vault 写入器 — 根据分类结果将内容写入正确的脑区。

支持两种人格模式（通过 PERSONA_MODE 切换）：
- "ENFP" — 能量地图 + 意义锚点 + 本周浮现
- "J" — 今日日志 + 决策日志 + 本周计划（默认模板）
"""
import os
import re
import logging
from pathlib import Path
from datetime import datetime

from .config import (
    VAULT_ROOT, INBOX_DIR, EXEC_DIR, WIKI_DIR,
    INBOX_INSPIRATION, INBOX_CONVERSATION, INBOX_TO_READ, INBOX_TO_PROCESS,
    EXEC_ENERGY, EXEC_EMERGE, EXEC_ANCHOR, EXEC_DECISION, EXEC_DAILY,
    EXEC_TRACKING,
)
from .classifier import Classification, Category

logger = logging.getLogger("friday-brain")

# ===========================================================================
# 人格模式切换 — 改这里改变 exec/ 的写入行为
# ===========================================================================
PERSONA_MODE = "ENFP"  # "ENFP" | "J"


def _timestamp() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


def _datestamp() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def _ensure_file_header(filepath: Path, header: str):
    """确保文件存在并有标题头。"""
    filepath.parent.mkdir(parents=True, exist_ok=True)
    if not filepath.exists():
        filepath.write_text(header + "\n\n", encoding="utf-8")


def route_and_write(classification: Classification, text: str,
                    user_name: str = "用户", source: str = "bot") -> str:
    """根据分类将内容写入 vault，返回给用户的确认消息。"""

    cat = classification.category
    title = classification.title or text[:30]
    ts = _timestamp()

    if cat == Category.QUERY:
        # 查询不写入 vault（由 knowledge 模块处理后可能写入）
        return _format_reply(cat, title, "")

    elif cat == Category.TASK:
        return _write_task(ts, text, title, user_name)

    elif cat == Category.DECISION:
        return _write_decision(ts, text, title, user_name)

    elif cat == Category.INSPIRATION:
        return _write_inspiration(ts, text, title, user_name)

    elif cat == Category.KNOWLEDGE:
        return _write_knowledge(ts, text, title, user_name)

    elif cat == Category.MEETING:
        return _write_meeting(ts, text, title, user_name)

    elif cat == Category.TODO:
        return _write_todo(ts, text, title, user_name)

    elif cat == Category.CHAT:
        return None  # 不存档，不回复确认

    return f"✅ 已记录"


def _format_reply(cat: Category, title: str, detail: str) -> str:
    """格式化给用户的确认回复。"""
    emoji_map = {
        Category.TASK: "📋",
        Category.DECISION: "🧭",
        Category.INSPIRATION: "💡",
        Category.KNOWLEDGE: "🧠",
        Category.MEETING: "🗣️",
        Category.TODO: "📌",
    }
    emoji = emoji_map.get(cat, "📝")
    cat_names = {
        Category.TASK: "任务追踪",
        Category.DECISION: "意义锚点",
        Category.INSPIRATION: "碎片灵感",
        Category.KNOWLEDGE: "知识待提炼",
        Category.MEETING: "对话记录",
        Category.TODO: "待办提醒",
    }
    name = cat_names.get(cat, cat.value)

    reply = f"{emoji} 已写入 {name}\n> {title}"
    if detail:
        reply += f"\n{detail}"
    return reply


# ---------------------------------------------------------------------------
# 各分类的写入逻辑
# ---------------------------------------------------------------------------

def _write_task(ts: str, text: str, title: str, user: str) -> str:
    """任务 → exec/追踪线/<标题>.md"""
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    task_file = EXEC_TRACKING / f"{safe_name}.md"

    if task_file.exists():
        entry = f"\n[{ts}] 📱 via {user}\n{text}\n"
        with open(task_file, "a", encoding="utf-8") as f:
            f.write(entry)
        return _format_reply(Category.TASK, title, f"→ 追加到已有追踪线 `追踪线/{safe_name}.md`")

    content = f"""---
created: {_datestamp()}
type: tracking
tags: [追踪线, 自动捕获]
source: {user}
---

# {title}

> 追踪线 — 自动从 IM 对话中捕获

## 进展记录

[{ts}] 📱 via {user}
{text}
"""
    task_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.TASK, title, f"→ 新建追踪线 `追踪线/{safe_name}.md`")


def _write_decision(ts: str, text: str, title: str, user: str) -> str:
    """决策 → 按人格模式写入不同文件"""
    if PERSONA_MODE == "ENFP":
        target = EXEC_ANCHOR
        _ensure_file_header(target,
            "# 意义锚点\n\n"
            "> ENFP 决策记录：不是「为什么选 A 不选 B」，"
            "而是「这件事对我的意义是什么，为什么我愿意投入」。\n"
        )
        entry = (
            f"## [{_datestamp()}] {title}\n\n"
            f"> 来源：{user} · {ts}\n\n"
            f"{text}\n\n"
            f"### 意义追问（Claudian 后续处理）\n"
            f"- 这个选择让我成为什么样的人？\n"
            f"- 如果放弃，我会后悔什么？\n\n"
            f"---\n\n"
        )
    else:
        target = EXEC_DECISION
        _ensure_file_header(target,
            "# 决策日志\n\n"
            "> 记录关键判断：为什么这样做？放弃了哪些选项？\n"
        )
        entry = (
            f"### [{_datestamp()}] {title}\n\n"
            f"- **情境**：{user} · {ts}\n"
            f"- **内容**：{text}\n"
            f"- **判断依据**：（待补充）\n"
            f"- **预期结果**：（待补充）\n"
            f"- **后续验证**：（待补充）\n\n"
            f"---\n\n"
        )

    with open(target, "a", encoding="utf-8") as f:
        f.write(entry)

    return _format_reply(Category.DECISION, title,
                         f"→ `{target.relative_to(VAULT_ROOT)}`")


def _write_inspiration(ts: str, text: str, title: str, user: str) -> str:
    """灵感 → inbox/碎片灵感/"""
    target = INBOX_INSPIRATION
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    insp_file = target / f"{_datestamp()}-{safe_name}.md"

    content = f"""---
created: {_datestamp()}
type: inspiration
source: {user} via bot
---

# {title}

> {ts} · 来自 {user}

{text}

---
*72h 内路由或丢弃 · 由 AI 主动提醒*
"""
    insp_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.INSPIRATION, title)


def _write_knowledge(ts: str, text: str, title: str, user: str) -> str:
    """知识 → inbox/待提炼/"""
    target = INBOX_TO_PROCESS
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    know_file = target / f"{_datestamp()}-{safe_name}.md"

    content = f"""---
created: {_datestamp()}
type: raw-knowledge
source: {user} via bot
---

# {title}

> {ts} · 来自 {user}

{text}

---
## 待提炼

- [ ] 核心观点是什么？
- [ ] 与现有 wiki 的哪些概念有关？
- [ ] 应该升级为实体/概念页面还是合并到已有页面？

*待 Claudian 在 Obsidian 中提炼*
"""
    know_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.KNOWLEDGE, title,
                         f"→ `inbox/待提炼/` · 等你打开 Obsidian 后我会提炼")


def _write_meeting(ts: str, text: str, title: str, user: str) -> str:
    """会议/对话 → inbox/对话记录/"""
    target = INBOX_CONVERSATION
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    meet_file = target / f"{_datestamp()}-{safe_name}.md"

    content = f"""---
created: {_datestamp()}
type: conversation-log
source: {user} via bot
---

# {title}

> {ts} · 来自 {user}

{text}

---
## 待提炼

- [ ] 关键人物/实体？
- [ ] 核心判断/决定？
- [ ] 可沉淀的知识/方法？
- [ ] 跟进事项？

*待 Claudian 在 Obsidian 中提炼结构化内容*
"""
    meet_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.MEETING, title,
                         f"→ `inbox/对话记录/` · 等你打开 Obsidian 后我会提炼")


def _write_todo(ts: str, text: str, title: str, user: str) -> str:
    """待办 → exec/当前能量区.md 或本周浮现"""
    if PERSONA_MODE == "ENFP":
        target = EXEC_EMERGE
        _ensure_file_header(target,
            "# 本周浮现\n\n"
            "> ENFP 执行记录：不提前计划「今天要做什么」，"
            "而是回顾「这周实际浮现了什么、我推动了什么」。\n\n"
            "## 本周记录\n"
        )
        entry = f"- [{ts}] 📌 {text}\n"
    else:
        target = EXEC_DAILY
        _ensure_file_header(target,
            "# 今日日志\n\n"
            "> 每天只推进 1-2 件关键事。\n\n"
            "## 今日要事\n\n"
            "1. \n2. \n\n"
            "## 今日收束\n\n"
            "- 做了什么：\n- 收获/感悟：\n- 明天要做什么：\n"
        )
        entry = f"- [{ts}] 📌 待办: {text}\n"

    with open(target, "a", encoding="utf-8") as f:
        f.write(entry)

    return _format_reply(Category.TODO, title,
                         f"→ `{target.relative_to(VAULT_ROOT)}`")

"""
知识检索 — 搜索 vault 中的知识并生成回答。

搜索策略：
1. 关键词匹配 wiki/ + skills/
2. Claude 综合回答（如果 API 可用）
"""
import re
import json
import logging
import time
from pathlib import Path

from .config import (
    WIKI_DIR, SKILLS_DIR, DOMAINS_DIR, VAULT_ROOT,
    CLAUDE_API_KEY, CLAUDE_MODEL, CLAUDE_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")

# 计算 DOMAINS_DIR
DOMAINS_DIR = VAULT_ROOT / "domains"

# 缓存
_cache = {"pages": {}, "loaded_at": 0}
CACHE_TTL = 300  # 5 分钟


def _load_all_pages():
    """加载 vault 中所有 markdown 页面到缓存。"""
    global _cache
    now = time.time()
    if now - _cache["loaded_at"] < CACHE_TTL and _cache["pages"]:
        return

    pages = {}
    search_dirs = [
        (WIKI_DIR, "wiki"),
        (SKILLS_DIR, "skills"),
        (DOMAINS_DIR, "domains"),
        (VAULT_ROOT / "exec", "exec"),
        (VAULT_ROOT / "inbox", "inbox"),
    ]

    for base_dir, prefix in search_dirs:
        if not base_dir.exists():
            continue
        for md_file in base_dir.rglob("*.md"):
            try:
                content = md_file.read_text(encoding="utf-8")
                # 跳过 frontmatter
                body = content
                if content.startswith("---"):
                    end = content.find("---", 3)
                    if end != -1:
                        body = content[end + 3:].strip()

                # 提取标题
                title = md_file.stem
                for line in content.split("\n"):
                    if line.startswith("# "):
                        title = line.lstrip("# ").strip()
                        break

                key = f"{prefix}/{md_file.relative_to(base_dir)}"
                pages[key] = {
                    "title": title,
                    "path": str(md_file),
                    "content": body,
                }
            except Exception:
                pass

    _cache["pages"] = pages
    _cache["loaded_at"] = now
    logger.info(f"知识库已加载: {len(pages)} 页")


def search(query: str, max_results: int = 5) -> list:
    """关键词搜索，返回相关页面列表。"""
    _load_all_pages()

    query_lower = query.lower()
    scored = []

    for key, page in _cache["pages"].items():
        score = 0
        # 标题精确匹配
        if query_lower in page["title"].lower():
            score += 50
        # 关键词匹配
        words = query_lower.split()
        for word in words:
            if len(word) > 1 and word in page["content"].lower():
                score += 3
        # 标题部分匹配
        for word in words:
            if len(word) > 1 and word in page["title"].lower():
                score += 10

        if score > 0:
            scored.append((score, page))

    scored.sort(key=lambda x: -x[0])
    return [p for _, p in scored[:max_results]]


def answer_query(query: str, user_name: str = "用户") -> str:
    """回答用户的查询。先用关键词搜索，如果 Claude 可用则综合回答。"""
    results = search(query)

    if not results:
        return (
            f"🤖 我在知识库中没有找到与「{query[:50]}」直接相关的内容。\n\n"
            f"已记录到收件箱，等你打开 Obsidian 后 Claudian 会帮你深入研究。"
        )

    # 构建知识上下文
    context_parts = []
    for page in results[:5]:
        body = page["content"][:500].strip()
        context_parts.append(f"📄 **{page['title']}**\n{body}")

    context = "\n\n---\n\n".join(context_parts)

    # 如果 Claude API 可用，用它综合回答
    if CLAUDE_API_KEY:
        try:
            return _claude_answer(query, context)
        except Exception as e:
            logger.warning(f"Claude 回答失败: {e}")

    # 关键词模式：返回搜索摘要
    return (
        f"🤖 知识库中找到相关内容：\n\n{context}\n\n"
        f"💡 如需更深入的分析，请打开 Obsidian 让 Claudian 处理。"
    )


def _claude_answer(query: str, context: str) -> str:
    """使用 Claude API 基于知识库上下文回答问题。"""
    import anthropic

    client = anthropic.Anthropic(api_key=CLAUDE_API_KEY)

    prompt = f"""你是 Friday 智脑的 AI 助手。基于以下知识库内容回答用户的问题。

知识库内容：
---
{context}
---

用户问题：
{query}

要求：
- 基于知识库内容回答，如果知识库没有的直接说"知识库中没有这部分信息"
- 用中文回答，简洁有条理
- 如果是关于智脑理论的问题，参考知识库中的相关概念页面
- 回答末尾可以建议用户打开 Obsidian 获取更详细的信息
- 控制在 300 字以内"""

    response = client.messages.create(
        model=CLAUDE_MODEL,
        max_tokens=CLAUDE_MAX_TOKENS,
        messages=[{"role": "user", "content": prompt}],
    )

    answer = response.content[0].text.strip()
    return f"🤖 {answer}\n\n💡 打开 Obsidian 可以让 Claudian 做更深入的分析。"

