"""
知识检索 — 搜索 vault 中的知识并生成回答。

搜索策略：
1. 关键词匹配 wiki/ + skills/
2. Claude 综合回答（如果 API 可用）
"""
import re
import json
import logging
import time
from pathlib import Path

from .config import (
    WIKI_DIR, SKILLS_DIR, DOMAINS_DIR, VAULT_ROOT,
    CLAUDE_API_KEY, CLAUDE_MODEL, CLAUDE_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")

# 计算 DOMAINS_DIR
DOMAINS_DIR = VAULT_ROOT / "domains"

# 缓存
_cache = {"pages": {}, "loaded_at": 0}
CACHE_TTL = 300  # 5 分钟


def _load_all_pages():
    """加载 vault 中所有 markdown 页面到缓存。"""
    global _cache
    now = time.time()
    if now - _cache["loaded_at"] < CACHE_TTL and _cache["pages"]:
        return

    pages = {}
    search_dirs = [
        (WIKI_DIR, "wiki"),
        (SKILLS_DIR, "skills"),
        (DOMAINS_DIR, "domains"),
        (VAULT_ROOT / "exec", "exec"),
        (VAULT_ROOT / "inbox", "inbox"),
    ]

    for base_dir, prefix in search_dirs:
        if not base_dir.exists():
            continue
        for md_file in base_dir.rglob("*.md"):
            try:
                content = md_file.read_text(encoding="utf-8")
                # 跳过 frontmatter
                body = content
                if content.startswith("---"):
                    end = content.find("---", 3)
                    if end != -1:
                        body = content[end + 3:].strip()

                # 提取标题
                title = md_file.stem
                for line in content.split("\n"):
                    if line.startswith("# "):
                        title = line.lstrip("# ").strip()
                        break

                key = f"{prefix}/{md_file.relative_to(base_dir)}"
                pages[key] = {
                    "title": title,
                    "path": str(md_file),
                    "content": body,
                }
            except Exception:
                pass

    _cache["pages"] = pages
    _cache["loaded_at"] = now
    logger.info(f"知识库已加载: {len(pages)} 页")


def search(query: str, max_results: int = 5) -> list:
    """关键词搜索，返回相关页面列表。"""
    _load_all_pages()

    query_lower = query.lower()
    scored = []

    for key, page in _cache["pages"].items():
        score = 0
        # 标题精确匹配
        if query_lower in page["title"].lower():
            score += 50
        # 关键词匹配
        words = query_lower.split()
        for word in words:
            if len(word) > 1 and word in page["content"].lower():
                score += 3
        # 标题部分匹配
        for word in words:
            if len(word) > 1 and word in page["title"].lower():
                score += 10

        if score > 0:
            scored.append((score, page))

    scored.sort(key=lambda x: -x[0])
    return [p for _, p in scored[:max_results]]


def answer_query(query: str, user_name: str = "用户") -> str:
    """回答用户的查询。先用关键词搜索，如果 Claude 可用则综合回答。"""
    results = search(query)

    if not results:
        return (
            f"🤖 我在知识库中没有找到与「{query[:50]}」直接相关的内容。\n\n"
            f"已记录到收件箱，等你打开 Obsidian 后 Claudian 会帮你深入研究。"
        )

    # 构建知识上下文
    context_parts = []
    for page in results[:5]:
        body = page["content"][:500].strip()
        context_parts.append(f"📄 **{page['title']}**\n{body}")

    context = "\n\n---\n\n".join(context_parts)

    # 如果 Claude API 可用，用它综合回答
    if CLAUDE_API_KEY:
        try:
            return _claude_answer(query, context)
        except Exception as e:
            logger.warning(f"Claude 回答失败: {e}")

    # 关键词模式：返回搜索摘要
    return (
        f"🤖 知识库中找到相关内容：\n\n{context}\n\n"
        f"💡 如需更深入的分析，请打开 Obsidian 让 Claudian 处理。"
    )


def _claude_answer(query: str, context: str) -> str:
    """使用 Claude API 基于知识库上下文回答问题。"""
    import anthropic

    client = anthropic.Anthropic(api_key=CLAUDE_API_KEY)

    prompt = f"""你是 Friday 智脑的 AI 助手。基于以下知识库内容回答用户的问题。

知识库内容：
---
{context}
---

用户问题：
{query}

要求：
- 基于知识库内容回答，如果知识库没有的直接说"知识库中没有这部分信息"
- 用中文回答，简洁有条理
- 如果是关于智脑理论的问题，参考知识库中的相关概念页面
- 回答末尾可以建议用户打开 Obsidian 获取更详细的信息
- 控制在 300 字以内"""

    response = client.messages.create(
        model=CLAUDE_MODEL,
        max_tokens=CLAUDE_MAX_TOKENS,
        messages=[{"role": "user", "content": prompt}],
    )

    answer = response.content[0].text.strip()
    return f"🤖 {answer}\n\n💡 打开 Obsidian 可以让 Claudian 做更深入的分析。"

