CACHE_TTL = 300  # 5 分钟


def _load_all_pages():
    """加载 vault 中所有 markdown 页面到缓存。"""
    global _cache
    now = time.time()
    if now - _cache["loaded_at"] < CACHE_TTL and _cache["pages"]:
        return

    pages = {}
    search_dirs = [
        (WIKI_DIR, "wiki"),
