"""
知识检索 — 搜索 vault 中的知识并生成回答。

搜索策略：
1. 关键词匹配 wiki/ + skills/
2. Claude 综合回答（如果 API 可用）
"""
import re
import json
import logging
import time
from pathlib import Path

from .config import (
    WIKI_DIR, SKILLS_DIR, VAULT_ROOT,
    LLM_PROVIDER, CLAUDE_API_KEY, CLAUDE_MODEL,
    DEEPSEEK_API_KEY, DEEPSEEK_BASE_URL, DEEPSEEK_MODEL,
    LLM_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")

# domains 目录
DOMAINS_DIR = VAULT_ROOT / "domains"

# 缓存
_cache = {"pages": {}, "loaded_at": 0}
CACHE_TTL = 300  # 5 分钟


def _load_all_pages():
    """加载 vault 中所有 markdown 页面到缓存。"""
    global _cache
    now = time.time()
    if now - _cache["loaded_at"] < CACHE_TTL and _cache["pages"]:
        return

    pages = {}
    search_dirs = [
        (WIKI_DIR, "wiki"),
        (SKILLS_DIR, "skills"),
        (DOMAINS_DIR, "domains"),
        (VAULT_ROOT / "exec", "exec"),
        (VAULT_ROOT / "inbox", "inbox"),
    ]

    for base_dir, prefix in search_dirs:
        if not base_dir.exists():
            continue
        for md_file in base_dir.rglob("*.md"):
            try:
                content = md_file.read_text(encoding="utf-8")
                # 跳过 frontmatter
                body = content
                if content.startswith("---"):
                    end = content.find("---", 3)
                    if end != -1:
                        body = content[end + 3:].strip()

                # 提取标题
                title = md_file.stem
                for line in content.split("\n"):
                    if line.startswith("# "):
                        title = line.lstrip("# ").strip()
                        break

                key = f"{prefix}/{md_file.relative_to(base_dir)}"
                pages[key] = {
                    "title": title,
                    "path": str(md_file),
                    "content": body,
                }
            except Exception:
                pass

    _cache["pages"] = pages
    _cache["loaded_at"] = now
    logger.info(f"知识库已加载: {len(pages)} 页")


def _extract_search_terms(text: str) -> list:
    """从搜索文本中提取有意义的词段（中文 n-gram + 英文单词）。"""
    import re
    terms = set()

    # 中文：提取 2-5 字片段
    chinese_chars = re.findall(r'[一-鿿]+', text)
    for segment in chinese_chars:
        for length in (4, 3, 2, 5):
            for i in range(len(segment) - length + 1):
                terms.add(segment[i:i + length])

    # 英文/数字：2 字符以上的单词
    english_words = re.findall(r'[a-z0-9]{2,}', text)
    terms.update(english_words)

    return list(terms)


def search(query: str, max_results: int = 5) -> list:
    """关键词搜索，返回相关页面列表。支持中文 n-gram 匹配。"""
    _load_all_pages()

    query_lower = query.lower()
    terms = _extract_search_terms(query_lower)
    scored = []

    for key, page in _cache["pages"].items():
        score = 0
        title_lower = page["title"].lower()
        content_lower = page["content"].lower()

        # 完整标题命中：查询中包含页面标题
        if title_lower and title_lower in query_lower:
            score += 60
        # 完整查询命中：标题中包含查询关键词
        elif query_lower in title_lower:
            score += 40
        # 词段匹配
        else:
            for term in terms:
                if term in title_lower:
                    score += 15
                if term in content_lower:
                    score += 2

        if score > 0:
            scored.append((score, page))

    scored.sort(key=lambda x: -x[0])
    return [p for _, p in scored[:max_results]]


def _get_llm_api_key() -> str | None:
    """获取当前 LLM 提供商的 API Key。"""
    if LLM_PROVIDER == "deepseek" and DEEPSEEK_API_KEY:
        return DEEPSEEK_API_KEY
    if LLM_PROVIDER == "claude" and CLAUDE_API_KEY:
        return CLAUDE_API_KEY
    return None


def answer_query(query: str, user_name: str = "用户") -> str:
    """回答用户查询。有 API Key 就用 LLM 综合回答，否则用关键词摘要。"""
    results = search(query)

    if not results:
        return (
            f"未找到「{query[:30]}」相关内容。\n"
            f"已记录，开 Obsidian 后帮你查。"
        )

    # 构建知识上下文
    context_parts = []
    for page in results[:3]:
        body = page["content"]
        if body.startswith("---"):
            end = body.find("---", 3)
            if end != -1:
                body = body[end + 3:]
        context_parts.append(f"## {page['title']}\n{body[:800].strip()}")

    context = "\n\n".join(context_parts)

    # 如果 LLM API 可用，用它综合回答
    api_key = _get_llm_api_key()
    if api_key:
        try:
            return _llm_answer(query, context, api_key)
        except Exception as e:
            logger.warning(f"LLM 回答失败，回退关键词: {e}")

    # 回退：关键词摘要
    best = results[0]
    title = best["title"]
    body = best["content"]
    if body.startswith("---"):
        end = body.find("---", 3)
        if end != -1:
            body = body[end + 3:]
    lines = body.strip().split("\n")
    summary_parts = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#") or line.startswith("> ") or \
           line.startswith("|") or line.startswith("-"):
            continue
        clean = line.replace("**", "").replace("`", "").replace("__", "")
        summary_parts.append(clean)
        if len("".join(summary_parts)) > 120:
            break
    summary = "".join(summary_parts)[:150]

    return (
        f"📄 {title}\n"
        f"{summary}...\n\n"
