        logger.error(f"Claude CLI 失败: {result.stderr[:200]}")
    except FileNotFoundError:
        logger.error("claude CLI 未找到，请确认 Claude Code 已安装且 claude 命令可用")
    except subprocess.TimeoutExpired:
        logger.error("Claude CLI 超时")
    except Exception as e:
