                    break  # lark-cli 挂了
                line = line.strip()
                if line:
                    logger.info(f"[lark-cli] {line[:200]}")
                if not line:
                    continue
                try:
                    json.loads(line)
                    handle_event(line)
                except json.JSONDecodeError:
                    pass

            # 每 5 秒检查代码是否变更
            now = time.time()
            if now - last_check > 5:
                if _any_changed(brain_dir, app_file, file_mtimes):
                    logger.info("检测到代码变更，自动重启...")
                    proc.terminate()
                    break
                last_check = now

