logger = logging.getLogger("friday-feishu")


def lark(*args, timeout=15):
    """调用 lark-cli 命令（Windows 通过 shell 启动 PowerShell 脚本）。"""
    return subprocess.run(
        "lark-cli " + " ".join(args),
        capture_output=True, text=True, timeout=timeout, shell=True,
    )


def send_message(chat_id: str, text: str):
    """发送消息回复。清洗文本避免破坏 shell 命令。"""
    clean = text.replace("\n", " ").replace("\r", "").replace('"', "'")[:500]
    try:
        r = lark("im", "+messages-send", "--chat-id", chat_id, "--text", f'"{clean}"')
        if r.returncode != 0:
            logger.error(f"发送失败: {r.stderr.strip()[:200]}")
        else:
            logger.info(f"已回复 {chat_id}")
    except Exception as e:
        logger.error(f"发送异常: {e}")


def get_user_name(open_id: str) -> str:
    """获取用户姓名。"""
    try:
        r = lark("contact", "user", "get", "--user-id", open_id, timeout=10)
        if r.returncode == 0 and r.stdout:
            data = json.loads(r.stdout)
            return data.get("data", {}).get("user", {}).get("name", open_id)
    except Exception:
        pass
    return open_id


def handle_event(line: str):
    """处理一条来自 lark-cli stdout 的 JSON 事件。"""
    # 每次处理前重载大脑——代码更新下一条消息就生效
    import importlib
    for mod in list(sys.modules.keys()):
        if mod.startswith("brain"):
            try:
                importlib.reload(sys.modules[mod])
            except Exception:
                pass

    try:
        event = json.loads(line)
    except json.JSONDecodeError:
        return  # 非 JSON 行，忽略

    # 只处理消息接收事件
    event_type = event.get("header", {}).get("event_type", "")
    if event_type != "im.message.receive_v1":
        return

    ev = event.get("event", {})
    message = ev.get("message", {})

    if message.get("message_type") != "text":
        return

    # 提取文本
    try:
        text = json.loads(message.get("content", "{}")).get("text", "").strip()
    except json.JSONDecodeError:
        return

    if not text:
        return

    open_id = ev.get("sender", {}).get("sender_id", {}).get("open_id", "")
    chat_id = message.get("chat_id", open_id)
    user_name = get_user_name(open_id)

    logger.info(f"收到消息 from={user_name}({open_id}): {text[:100]}")

    # 共享大脑（重载后获取最新版）
    from brain import process_message as pm
    try:
        reply = pm(text, user_name=user_name or open_id, source="feishu")
    except Exception as e:
        logger.error(f"大脑异常: {e}", exc_info=True)
        reply = "处理消息时遇到问题，已记录。"

    # 备份
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    inbox_req = Path(__file__).resolve().parent.parent.parent / "inbox" / "requests.md"
    with open(inbox_req, "a", encoding="utf-8") as f:
        f.write(f"### [{ts}] 🕊️ 飞书 | {user_name or open_id}\n{text}\n\n---\n\n")

    # 回复
    if reply:
        send_message(chat_id, reply)


def _watch_files(brain_dir: Path, app_file: Path) -> dict:
    """记录当前文件修改时间，用于检测代码变更。"""
    mtimes = {}
    for f in brain_dir.rglob("*.py"):
        mtimes[str(f)] = f.stat().st_mtime
    mtimes[str(app_file)] = app_file.stat().st_mtime
    return mtimes


def _any_changed(brain_dir: Path, app_file: Path, old_mtimes: dict) -> bool:
    """检查是否有代码文件被修改。"""
    try:
        for f in brain_dir.rglob("*.py"):
            if str(f) not in old_mtimes or f.stat().st_mtime != old_mtimes[str(f)]:
                return True
        if app_file.stat().st_mtime != old_mtimes.get(str(app_file), 0):
            return True
    except Exception:
        pass
    return False


def main():
    """启动 lark-cli 事件订阅 + 文件监控自动重启。"""
    brain_dir = Path(__file__).resolve().parent.parent / "brain"
    app_file = Path(__file__).resolve()

    while True:
        logger.info("Friday 智脑 Bot (纯 lark-cli) 启动")

        # 检查 lark-cli
        try:
            subprocess.run("lark-cli --version", capture_output=True, timeout=5, shell=True)
        except FileNotFoundError:
            logger.error("lark-cli 未安装！npm install -g @larksuite/cli")
            sys.exit(1)

        # 记录文件时间戳
        file_mtimes = _watch_files(brain_dir, app_file)

        logger.info("启动 lark-cli 事件订阅...")
        proc = subprocess.Popen(
            "lark-cli event +subscribe --event-types im.message.receive_v1",
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, shell=True, bufsize=1,
        )

        logger.info("等待飞书消息... (代码变更自动重启)")

        import select
        last_check = time.time()

        while True:
            # 非阻塞读 stdout（超时 5 秒，用于文件检查）
            if select.select([proc.stdout], [], [], 5)[0]:
                line = proc.stdout.readline()
                if not line:
                    break  # lark-cli 挂了
                line = line.strip()
                if line:
                    logger.info(f"[lark-cli] {line[:200]}")
                if not line:
                    continue
                try:
                    json.loads(line)
                    handle_event(line)
                except json.JSONDecodeError:
                    pass

            # 每 5 秒检查代码是否变更
            now = time.time()
            if now - last_check > 5:
                if _any_changed(brain_dir, app_file, file_mtimes):
                    logger.info("检测到代码变更，自动重启...")
                    proc.terminate()
                    break
                last_check = now

        proc.terminate()
        logger.info("重启中...")

