            # 每 5 秒检查代码是否变更
            now = time.time()
            if now - last_check > 5:
                if _any_changed(brain_dir, app_file, file_mtimes):
                    logger.info("检测到代码变更，自动重启...")
                    proc.terminate()
                    break
                last_check = now

        proc.terminate()
        logger.info("重启中...")

# ---------------------------------------------------------------------------
# CLI 测试模式
# ---------------------------------------------------------------------------
def cli_mode():
    print("\n  Friday 智脑 Bot (纯 lark-cli) — CLI 测试模式\n")
    print("  输入消息测试分类和路由，输入 quit 退出\n")
    while True:
        try:
            text = input("  You > ").strip()
            if text.lower() in ("quit", "exit", "q"):
                break
            if not text:
                continue
            reply = process_message(text, user_name="CLI测试", source="feishu-cli")
            if reply:
                print(f"\n  Bot > {reply}\n")
            else:
                print(f"  (已写入 vault，无需回复)\n")
        except KeyboardInterrupt:
            print("\n")
            break
        except Exception as e:
            print(f"  Error: {e}\n")
    print("  已退出 CLI 模式\n")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Friday 智脑 — 飞书 Bot")
    parser.add_argument("--cli", action="store_true")
    args = parser.parse_args()

    if args.cli:
        cli_mode()
    else:
        main()

