"""
飞书机器人 — Friday 智脑 Bot（纯 lark-cli 版）
================================================
lark-cli 负责飞书通信，本脚本负责协调大脑。

架构：
  lark-cli event +subscribe → stdout JSON → 本脚本读取
      ↓ 提取消息文本
  shared brain 分类 + 写入 vault
      ↓ 返回回复
  lark-cli im +messages-send ← 本脚本调用

零外部 Python 依赖。只依赖 lark-cli（npm install -g @larksuite/cli）。
"""
import sys
import os
import time
import json
import logging
import threading
import subprocess
from pathlib import Path
from queue import Queue, Empty

# 修复 Windows 上 npm 全局包的 PATH
for npm_path in [
    os.path.expandvars(r"%APPDATA%\npm"),
    os.path.expandvars(r"%USERPROFILE%\AppData\Roaming\npm"),
    os.path.expanduser("~\\AppData\\Roaming\\npm"),
]:
    if os.path.isdir(npm_path) and npm_path not in os.environ.get("PATH", ""):
        os.environ["PATH"] = npm_path + os.pathsep + os.environ.get("PATH", "")

from datetime import datetime

# 添加 system/ 到 path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from brain import process_message

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [friday] %(levelname)s %(message)s",
    handlers=[
        logging.StreamHandler(),
        logging.FileHandler(Path(__file__).parent / "bot.log", encoding="utf-8"),
    ],
)
logger = logging.getLogger("friday-feishu")


def lark(*args, timeout=15):
    """调用 lark-cli 命令（Windows 通过 shell 启动 PowerShell 脚本）。"""
    return subprocess.run(
        "lark-cli " + " ".join(args),
        capture_output=True, text=True, timeout=timeout, shell=True,
    )


def send_message(chat_id: str, text: str):
    """发送消息回复。清洗文本避免破坏 shell 命令。"""
    clean = text.replace("\n", " ").replace("\r", "").replace('"', "'")[:500]
    try:
        r = lark("im", "+messages-send", "--chat-id", chat_id, "--text", f'"{clean}"')
        if r.returncode != 0:
            logger.error(f"发送失败: {r.stderr.strip()[:200]}")
        else:
            logger.info(f"已回复 {chat_id}")
    except Exception as e:
        logger.error(f"发送异常: {e}")


def get_user_name(open_id: str) -> str:
    """获取用户姓名。"""
    try:
        r = lark("contact", "user", "get", "--user-id", open_id, timeout=10)
        if r.returncode == 0 and r.stdout:
            data = json.loads(r.stdout)
            return data.get("data", {}).get("user", {}).get("name", open_id)
    except Exception:
        pass
    return open_id


def handle_event(line: str):
    """处理一条来自 lark-cli stdout 的 JSON 事件。"""
    # 每次处理前重载大脑——代码更新下一条消息就生效
    import importlib
    for mod in list(sys.modules.keys()):
        if mod.startswith("brain"):
            try:
                importlib.reload(sys.modules[mod])
            except Exception:
                pass

    try:
        event = json.loads(line)
    except json.JSONDecodeError:
        return  # 非 JSON 行，忽略

    # 只处理消息接收事件
    event_type = event.get("header", {}).get("event_type", "")
    if event_type != "im.message.receive_v1":
        return

    ev = event.get("event", {})
    message = ev.get("message", {})

    if message.get("message_type") != "text":
        return

    # 提取文本
    try:
        text = json.loads(message.get("content", "{}")).get("text", "").strip()
    except json.JSONDecodeError:
        return

    if not text:
        return

    open_id = ev.get("sender", {}).get("sender_id", {}).get("open_id", "")
    chat_id = message.get("chat_id", open_id)
    user_name = get_user_name(open_id)

    logger.info(f"收到消息 from={user_name}({open_id}): {text[:100]}")

    # 共享大脑（重载后获取最新版）
    from brain import process_message as pm
    try:
        reply = pm(text, user_name=user_name or open_id, source="feishu")
    except Exception as e:
        logger.error(f"大脑异常: {e}", exc_info=True)
        reply = "处理消息时遇到问题，已记录。"

    # 备份
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    inbox_req = Path(__file__).resolve().parent.parent.parent / "inbox" / "requests.md"
    with open(inbox_req, "a", encoding="utf-8") as f:
        f.write(f"### [{ts}] 🕊️ 飞书 | {user_name or open_id}\n{text}\n\n---\n\n")

    # 回复
    if reply:
        send_message(chat_id, reply)


def _watch_files(brain_dir: Path, app_file: Path) -> dict:
    """记录当前文件修改时间，用于检测代码变更。"""
    mtimes = {}
    for f in brain_dir.rglob("*.py"):
        mtimes[str(f)] = f.stat().st_mtime
    mtimes[str(app_file)] = app_file.stat().st_mtime
    return mtimes


def _any_changed(brain_dir: Path, app_file: Path, old_mtimes: dict) -> bool:
    """检查是否有代码文件被修改。"""
    try:
        for f in brain_dir.rglob("*.py"):
            if str(f) not in old_mtimes or f.stat().st_mtime != old_mtimes[str(f)]:
                return True
        if app_file.stat().st_mtime != old_mtimes.get(str(app_file), 0):
            return True
    except Exception:
        pass
    return False


def main():
    """启动 lark-cli 事件订阅 + 文件监控自动重启。"""
    brain_dir = Path(__file__).resolve().parent.parent / "brain"
    app_file = Path(__file__).resolve()

    while True:
        logger.info("Friday 智脑 Bot (纯 lark-cli) 启动")

        # 检查 lark-cli
        try:
            subprocess.run("lark-cli --version", capture_output=True, timeout=5, shell=True)
        except FileNotFoundError:
            logger.error("lark-cli 未安装！npm install -g @larksuite/cli")
            sys.exit(1)

        # 记录文件时间戳
        file_mtimes = _watch_files(brain_dir, app_file)

        logger.info("启动 lark-cli 事件订阅...")
        proc = subprocess.Popen(
            "lark-cli event +subscribe --event-types im.message.receive_v1",
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, shell=True, bufsize=1,
        )

        logger.info("等待飞书消息... (代码变更自动重启)")

        line_queue = Queue()

        def read_stdout():
            """后台线程：持续读取 lark-cli stdout。"""
            try:
                for line in proc.stdout:
                    line_queue.put(line)
            except Exception:
                pass

        reader = threading.Thread(target=read_stdout, daemon=True)
        reader.start()

        last_check = time.time()

        while reader.is_alive():
            try:
                line = line_queue.get(timeout=5).strip()
                if line:
                    logger.info(f"[lark-cli] {line[:200]}")
                if not line:
                    continue
                try:
                    json.loads(line)
                    handle_event(line)
                except json.JSONDecodeError:
                    pass
            except Empty:
                pass  # 超时，检查文件变更

            # 检查代码变更
            now = time.time()
            if now - last_check > 5:
                if _any_changed(brain_dir, app_file, file_mtimes):
                    logger.info("检测到代码变更，自动重启...")
                    break
                last_check = now

        proc.terminate()
        logger.info("重启中...")

# ---------------------------------------------------------------------------
# CLI 测试模式
# ---------------------------------------------------------------------------
def cli_mode():
    print("\n  Friday 智脑 Bot (纯 lark-cli) — CLI 测试模式\n")
    print("  输入消息测试分类和路由，输入 quit 退出\n")
    while True:
        try:
            text = input("  You > ").strip()
            if text.lower() in ("quit", "exit", "q"):
                break
            if not text:
                continue
            reply = process_message(text, user_name="CLI测试", source="feishu-cli")
            if reply:
                print(f"\n  Bot > {reply}\n")
            else:
                print(f"  (已写入 vault，无需回复)\n")
        except KeyboardInterrupt:
            print("\n")
            break
        except Exception as e:
            print(f"  Error: {e}\n")
    print("  已退出 CLI 模式\n")


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Friday 智脑 — 飞书 Bot")
    parser.add_argument("--cli", action="store_true")
    args = parser.parse_args()

    if args.cli:
        cli_mode()
    else:
        main()

"""
消息分类器 — 判断用户消息应该路由到哪个脑区。

分类策略（两层）：
1. 关键词匹配 — 快速、免费、可离线
2. Claude API — 准确、理解上下文（如果配置了 API key）
"""
import re
import json
import logging
from enum import Enum
from datetime import datetime

from .config import (
    CATEGORY_PATTERNS, QUERY_PATTERNS, CHAT_PATTERNS,
    LLM_PROVIDER, CLAUDE_API_KEY, CLAUDE_MODEL,
    DEEPSEEK_API_KEY, DEEPSEEK_BASE_URL, DEEPSEEK_MODEL, LLM_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")


class Category(Enum):
    QUERY = "QUERY"           # 查知识/提问
    TASK = "TASK"             # 要做的任务
    DECISION = "DECISION"     # 做出的判断/决策
    INSPIRATION = "INSPIRATION"  # 碎片灵感
    KNOWLEDGE = "KNOWLEDGE"   # 值得保存的知识/洞察
    MEETING = "MEETING"       # 会议/对话记录
    TODO = "TODO"             # 待办提醒
    CHAT = "CHAT"             # 闲聊，不存档


class Classification:
    """一条消息的分类结果"""
    def __init__(self, category: Category, title: str = "",
                 summary: str = "", confidence: float = 0.5,
                 target_subfolder: str = ""):
        self.category = category
        self.title = title
        self.summary = summary
        self.confidence = confidence
        self.target_subfolder = target_subfolder
        self.timestamp = datetime.now()

    def __repr__(self):
        return f"Classification({self.category.value}, '{self.title}', conf={self.confidence:.0%})"


def classify(text: str) -> Classification:
    """分类一条消息。先尝试关键词，关键词不确定时用 Claude。"""
    text = text.strip()
    if not text:
        return Classification(Category.CHAT, confidence=1.0)

    # 第一层：关键词匹配
    result = _keyword_classify(text)
    if result.confidence >= 0.7:
        return result

    # 第二层：LLM API（如果可用）
    api_key = _get_api_key()
    if api_key:
        try:
            return _llm_classify(text, api_key)
        except Exception as e:
            logger.warning(f"LLM 分类失败，回退到关键词: {e}")

    return result


def _keyword_classify(text: str) -> Classification:
    """基于关键词和正则的分类。"""

    # 先检查是否明确是闲聊
    for pattern in CHAT_PATTERNS:
        if re.search(pattern, text):
            return Classification(Category.CHAT, confidence=0.9)

    # 检查是否是查询
    for pattern in QUERY_PATTERNS:
        if re.search(pattern, text):
            return Classification(
                Category.QUERY,
                title=f"查询: {text[:30]}",
                summary=text,
                confidence=0.8,
            )

    # 匹配各类操作模式
    best_score = 0
    best_category = None

    for cat_name, patterns in CATEGORY_PATTERNS.items():
        score = 0
        for pattern in patterns:
            if re.search(pattern, text):
                score += 1
        if score > best_score:
            best_score = score
            best_category = Category[cat_name]

    if best_score >= 2:
        confidence = min(0.9, 0.4 + best_score * 0.2)
        title = _extract_title(text, best_category)
        return Classification(best_category, title=title, summary=text,
                              confidence=confidence)

    if best_score >= 1:
        title = _extract_title(text, best_category)
        return Classification(best_category, title=title, summary=text,
                              confidence=0.5)

    # 默认：如果文本较长，可能是灵感；如果短，可能是闲聊
    if len(text) > 30:
        return Classification(
            Category.INSPIRATION,
            title=text[:30],
            summary=text,
            confidence=0.3,
        )
    return Classification(Category.CHAT, confidence=0.3)


def _extract_title(text: str, category: Category) -> str:
    """从文本中提取简短标题。"""
    # 去掉命令前缀
    clean = re.sub(r'^[#/]\w+\s+', '', text).strip()
    # 取第一句话或前 30 字
    sentences = re.split(r'[。！？\n]', clean)
    first = sentences[0].strip() if sentences else clean
    if len(first) > 30:
        first = first[:30] + "…"
    return first


def _get_api_key() -> str | None:
    """获取当前 LLM 提供商的 API Key。claudian 不需要。"""
    if LLM_PROVIDER == "claudian":
        return "local"
    if LLM_PROVIDER == "deepseek" and DEEPSEEK_API_KEY:
        return DEEPSEEK_API_KEY
    if LLM_PROVIDER == "claude" and CLAUDE_API_KEY:
        return CLAUDE_API_KEY
    return None


def _llm_classify(text: str, api_key: str) -> Classification:
    """使用 LLM API 进行智能分类。"""
    categories_desc = "\n".join([
        "QUERY - 查知识/提问", "TASK - 要做的任务", "DECISION - 做出的判断",
        "INSPIRATION - 碎片灵感", "KNOWLEDGE - 值得保存的知识",
        "MEETING - 会议/对话记录", "TODO - 待办提醒", "CHAT - 闲聊",
    ])

    prompt = f"""分析这条消息，判断它属于哪一类。

消息内容：
---
{text}
---

可选类别：
{categories_desc}

返回 JSON：{{"category": "分类名", "title": "简短标题", "summary": "一句话摘要", "confidence": 0.9}}
如果包含问号或明显在提问 → QUERY。title 和 summary 用中文。只返回 JSON。"""

    if LLM_PROVIDER == "deepseek":
        return _parse_llm_response(_call_deepseek(prompt, api_key))
    else:
        return _parse_llm_response(_call_claude(prompt, api_key))


def _call_deepseek(prompt: str, api_key: str) -> str:
    from openai import OpenAI
    client = OpenAI(api_key=api_key, base_url=DEEPSEEK_BASE_URL)
    r = client.chat.completions.create(
        model=DEEPSEEK_MODEL, messages=[{"role": "user", "content": prompt}],
        max_tokens=LLM_MAX_TOKENS,
    )
    return r.choices[0].message.content.strip()


def _call_claude(prompt: str, api_key: str) -> str:
    import anthropic
    client = anthropic.Anthropic(api_key=api_key)
    r = client.messages.create(
        model=CLAUDE_MODEL,
        max_tokens=LLM_MAX_TOKENS,
        messages=[{"role": "user", "content": prompt}],
    )
    return r.content[0].text.strip()


def _parse_llm_response(result_text: str) -> Classification:
    result_text = re.sub(r'^```(?:json)?\s*', '', result_text.strip())
    result_text = re.sub(r'\s*```$', '', result_text)

    try:
        data = json.loads(result_text)
    except json.JSONDecodeError:
        logger.warning(f"LLM 返回非 JSON: {result_text[:100]}")
        return _keyword_classify(text)

    try:
        category = Category[data["category"]]
    except KeyError:
        category = Category.INSPIRATION

    return Classification(
        category=category,
        title=data.get("title", text[:20]),
        summary=data.get("summary", text[:50]),
        confidence=data.get("confidence", 0.7),
    )

"""
Vault 写入器 — 根据分类结果将内容写入正确的脑区。

支持两种人格模式（通过 PERSONA_MODE 切换）：
- "ENFP" — 能量地图 + 意义锚点 + 本周浮现
- "J" — 今日日志 + 决策日志 + 本周计划（默认模板）
"""
import os
import re
import logging
from pathlib import Path
from datetime import datetime

from .config import (
    VAULT_ROOT, INBOX_DIR, EXEC_DIR, WIKI_DIR,
    INBOX_INSPIRATION, INBOX_CONVERSATION, INBOX_TO_READ, INBOX_TO_PROCESS,
    EXEC_ENERGY, EXEC_EMERGE, EXEC_ANCHOR, EXEC_DECISION, EXEC_DAILY,
    EXEC_TRACKING,
)
from .classifier import Classification, Category

logger = logging.getLogger("friday-brain")

# ===========================================================================
# 人格模式切换 — 改这里改变 exec/ 的写入行为
# ===========================================================================
PERSONA_MODE = "ENFP"  # "ENFP" | "J"


def _timestamp() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


def _datestamp() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def _ensure_file_header(filepath: Path, header: str):
    """确保文件存在并有标题头。"""
    filepath.parent.mkdir(parents=True, exist_ok=True)
    if not filepath.exists():
        filepath.write_text(header + "\n\n", encoding="utf-8")


def route_and_write(classification: Classification, text: str,
                    user_name: str = "用户", source: str = "bot") -> str:
    """根据分类将内容写入 vault，返回给用户的确认消息。"""

    cat = classification.category
    title = classification.title or text[:30]
    ts = _timestamp()

    if cat == Category.QUERY:
        # 查询不写入 vault（由 knowledge 模块处理后可能写入）
        return _format_reply(cat, title, "")

    elif cat == Category.TASK:
        return _write_task(ts, text, title, user_name)

    elif cat == Category.DECISION:
        return _write_decision(ts, text, title, user_name)

    elif cat == Category.INSPIRATION:
        return _write_inspiration(ts, text, title, user_name)

    elif cat == Category.KNOWLEDGE:
        return _write_knowledge(ts, text, title, user_name)

    elif cat == Category.MEETING:
        return _write_meeting(ts, text, title, user_name)

    elif cat == Category.TODO:
        return _write_todo(ts, text, title, user_name)

    elif cat == Category.CHAT:
        return None  # 不存档，不回复确认

    return f"✅ 已记录"


def _format_reply(cat: Category, title: str, detail: str = "") -> str:
    """格式化给用户的确认回复。"""
    emoji_map = {
        Category.TASK: "📋",
        Category.DECISION: "🧭",
        Category.INSPIRATION: "💡",
        Category.KNOWLEDGE: "🧠",
        Category.MEETING: "🗣️",
        Category.TODO: "📌",
    }
    emoji = emoji_map.get(cat, "📝")
    cat_names = {
        Category.TASK: "任务追踪",
        Category.DECISION: "意义锚点",
        Category.INSPIRATION: "碎片灵感",
        Category.KNOWLEDGE: "知识待提炼",
        Category.MEETING: "对话记录",
        Category.TODO: "待办提醒",
    }
    name = cat_names.get(cat, cat.value)

    reply = f"{emoji} 已写入 {name}\n> {title}"
    if detail:
        reply += f"\n{detail}"
    return reply


# ---------------------------------------------------------------------------
# 各分类的写入逻辑
# ---------------------------------------------------------------------------

def _write_task(ts: str, text: str, title: str, user: str) -> str:
    """任务 → exec/追踪线/<标题>.md"""
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    task_file = EXEC_TRACKING / f"{safe_name}.md"

    if task_file.exists():
        entry = f"\n[{ts}] 📱 via {user}\n{text}\n"
        with open(task_file, "a", encoding="utf-8") as f:
            f.write(entry)
        return _format_reply(Category.TASK, title, f"→ 追加到已有追踪线 `追踪线/{safe_name}.md`")

    content = f"""---
created: {_datestamp()}
type: tracking
tags: [追踪线, 自动捕获]
source: {user}
---

# {title}

> 追踪线 — 自动从 IM 对话中捕获

## 进展记录

[{ts}] 📱 via {user}
{text}
"""
    task_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.TASK, title, f"→ 新建追踪线 `追踪线/{safe_name}.md`")


def _write_decision(ts: str, text: str, title: str, user: str) -> str:
    """决策 → 按人格模式写入不同文件"""
    if PERSONA_MODE == "ENFP":
        target = EXEC_ANCHOR
        _ensure_file_header(target,
            "# 意义锚点\n\n"
            "> ENFP 决策记录：不是「为什么选 A 不选 B」，"
            "而是「这件事对我的意义是什么，为什么我愿意投入」。\n"
        )
        entry = (
            f"## [{_datestamp()}] {title}\n\n"
            f"> 来源：{user} · {ts}\n\n"
            f"{text}\n\n"
            f"### 意义追问（Claudian 后续处理）\n"
