    # 只处理消息接收事件
    event_type = event.get("header", {}).get("event_type", "")
    if event_type != "im.message.receive_v1":
        return

    ev = event.get("event", {})
    message = ev.get("message", {})

    if message.get("message_type") != "text":
        return

    # 提取文本
    try:
        text = json.loads(message.get("content", "{}")).get("text", "").strip()
    except json.JSONDecodeError:
        return

    if not text:
        return

    open_id = ev.get("sender", {}).get("sender_id", {}).get("open_id", "")
    chat_id = message.get("chat_id", open_id)
    user_name = get_user_name(open_id)

    logger.info(f"收到消息 from={user_name}({open_id}): {text[:100]}")

    # 共享大脑（重载后获取最新版）
    from brain import process_message as pm
    try:
        reply = pm(text, user_name=user_name or open_id, source="feishu")
    except Exception as e:
        logger.error(f"大脑异常: {e}", exc_info=True)
        reply = "处理消息时遇到问题，已记录。"

    # 备份
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    inbox_req = Path(__file__).resolve().parent.parent.parent / "inbox" / "requests.md"
    with open(inbox_req, "a", encoding="utf-8") as f:
        f.write(f"### [{ts}] 🕊️ 飞书 | {user_name or open_id}\n{text}\n\n---\n\n")

    # 回复
    if reply:
        send_message(chat_id, reply)


def _watch_files(brain_dir: Path, app_file: Path) -> dict:
    """记录当前文件修改时间，用于检测代码变更。"""
    mtimes = {}
    for f in brain_dir.rglob("*.py"):
        mtimes[str(f)] = f.stat().st_mtime
    mtimes[str(app_file)] = app_file.stat().st_mtime
    return mtimes


def _any_changed(brain_dir: Path, app_file: Path, old_mtimes: dict) -> bool:
    """检查是否有代码文件被修改。"""
    try:
        for f in brain_dir.rglob("*.py"):
            if str(f) not in old_mtimes or f.stat().st_mtime != old_mtimes[str(f)]:
                return True
        if app_file.stat().st_mtime != old_mtimes.get(str(app_file), 0):
            return True
    except Exception:
        pass
    return False


def main():
