"""
消息分类器 — 判断用户消息应该路由到哪个脑区。

分类策略（两层）：
1. 关键词匹配 — 快速、免费、可离线
2. Claude API — 准确、理解上下文（如果配置了 API key）
"""
import re
import json
import logging
from enum import Enum
from datetime import datetime

from .config import (
    CATEGORY_PATTERNS, QUERY_PATTERNS, CHAT_PATTERNS,
    LLM_PROVIDER, CLAUDE_API_KEY, CLAUDE_MODEL,
    DEEPSEEK_API_KEY, DEEPSEEK_BASE_URL, DEEPSEEK_MODEL, LLM_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")


class Category(Enum):
    QUERY = "QUERY"           # 查知识/提问
    TASK = "TASK"             # 要做的任务
    DECISION = "DECISION"     # 做出的判断/决策
    INSPIRATION = "INSPIRATION"  # 碎片灵感
    KNOWLEDGE = "KNOWLEDGE"   # 值得保存的知识/洞察
    MEETING = "MEETING"       # 会议/对话记录
    TODO = "TODO"             # 待办提醒
    CHAT = "CHAT"             # 闲聊，不存档


class Classification:
    """一条消息的分类结果"""
    def __init__(self, category: Category, title: str = "",
                 summary: str = "", confidence: float = 0.5,
                 target_subfolder: str = ""):
        self.category = category
        self.title = title
        self.summary = summary
        self.confidence = confidence
        self.target_subfolder = target_subfolder
        self.timestamp = datetime.now()

    def __repr__(self):
        return f"Classification({self.category.value}, '{self.title}', conf={self.confidence:.0%})"


def classify(text: str) -> Classification:
    """分类一条消息。先尝试关键词，关键词不确定时用 Claude。"""
    text = text.strip()
    if not text:
        return Classification(Category.CHAT, confidence=1.0)

    # 第一层：关键词匹配
    result = _keyword_classify(text)
    if result.confidence >= 0.7:
        return result

    # 第二层：LLM API（如果可用）
    api_key = _get_api_key()
    if api_key:
        try:
            return _llm_classify(text, api_key)
        except Exception as e:
            logger.warning(f"LLM 分类失败，回退到关键词: {e}")

    return result


def _keyword_classify(text: str) -> Classification:
    """基于关键词和正则的分类。"""

    # 先检查是否明确是闲聊
    for pattern in CHAT_PATTERNS:
        if re.search(pattern, text):
            return Classification(Category.CHAT, confidence=0.9)

    # 检查是否是查询
    for pattern in QUERY_PATTERNS:
        if re.search(pattern, text):
            return Classification(
                Category.QUERY,
                title=f"查询: {text[:30]}",
                summary=text,
                confidence=0.8,
            )

    # 匹配各类操作模式
    best_score = 0
    best_category = None

    for cat_name, patterns in CATEGORY_PATTERNS.items():
        score = 0
        for pattern in patterns:
            if re.search(pattern, text):
                score += 1
        if score > best_score:
            best_score = score
            best_category = Category[cat_name]

    if best_score >= 2:
        confidence = min(0.9, 0.4 + best_score * 0.2)
        title = _extract_title(text, best_category)
        return Classification(best_category, title=title, summary=text,
                              confidence=confidence)

    if best_score >= 1:
        title = _extract_title(text, best_category)
        return Classification(best_category, title=title, summary=text,
                              confidence=0.5)

    # 默认：如果文本较长，可能是灵感；如果短，可能是闲聊
    if len(text) > 30:
        return Classification(
            Category.INSPIRATION,
            title=text[:30],
            summary=text,
            confidence=0.3,
        )
    return Classification(Category.CHAT, confidence=0.3)


def _extract_title(text: str, category: Category) -> str:
    """从文本中提取简短标题。"""
    # 去掉命令前缀
    clean = re.sub(r'^[#/]\w+\s+', '', text).strip()
    # 取第一句话或前 30 字
    sentences = re.split(r'[。！？\n]', clean)
    first = sentences[0].strip() if sentences else clean
    if len(first) > 30:
        first = first[:30] + "…"
    return first


def _get_api_key() -> str | None:
    """获取当前 LLM 提供商的 API Key。claudian 不需要。"""
    if LLM_PROVIDER == "claudian":
        return "local"
    if LLM_PROVIDER == "deepseek" and DEEPSEEK_API_KEY:
        return DEEPSEEK_API_KEY
    if LLM_PROVIDER == "claude" and CLAUDE_API_KEY:
        return CLAUDE_API_KEY
    return None


def _llm_classify(text: str, api_key: str) -> Classification:
    """使用 LLM API 进行智能分类。"""
    categories_desc = "\n".join([
        "QUERY - 查知识/提问", "TASK - 要做的任务", "DECISION - 做出的判断",
        "INSPIRATION - 碎片灵感", "KNOWLEDGE - 值得保存的知识",
        "MEETING - 会议/对话记录", "TODO - 待办提醒", "CHAT - 闲聊",
    ])

    prompt = f"""分析这条消息，判断它属于哪一类。

消息内容：
---
{text}
---

可选类别：
{categories_desc}

返回 JSON：{{"category": "分类名", "title": "简短标题", "summary": "一句话摘要", "confidence": 0.9}}
如果包含问号或明显在提问 → QUERY。title 和 summary 用中文。只返回 JSON。"""

    if LLM_PROVIDER == "deepseek":
        return _parse_llm_response(_call_deepseek(prompt, api_key), text)
    else:
        return _parse_llm_response(_call_claude(prompt, api_key), text)


def _call_deepseek(prompt: str, api_key: str) -> str:
    from openai import OpenAI
    client = OpenAI(api_key=api_key, base_url=DEEPSEEK_BASE_URL)
    r = client.chat.completions.create(
        model=DEEPSEEK_MODEL, messages=[{"role": "user", "content": prompt}],
        max_tokens=LLM_MAX_TOKENS,
    )
    return r.choices[0].message.content.strip()


def _call_claude(prompt: str, api_key: str) -> str:
    import anthropic
    client = anthropic.Anthropic(api_key=api_key)
    r = client.messages.create(
        model=CLAUDE_MODEL,
        max_tokens=LLM_MAX_TOKENS,
        messages=[{"role": "user", "content": prompt}],
    )
    return r.content[0].text.strip()


def _parse_llm_response(result_text: str, fallback_text: str = "未知") -> Classification:
    result_text = re.sub(r'^```(?:json)?\s*', '', result_text.strip())
    result_text = re.sub(r'\s*```$', '', result_text)

    try:
        data = json.loads(result_text)
    except json.JSONDecodeError:
        logger.warning(f"LLM 返回非 JSON: {result_text[:100]}")
        return _keyword_classify(fallback_text)

    try:
        category = Category[data["category"]]
    except KeyError:
        category = Category.INSPIRATION

    return Classification(
        category=category,
        title=data.get("title", fallback_text[:20]),
        summary=data.get("summary", fallback_text[:50]),
        confidence=data.get("confidence", 0.7),
    )

