"""
Vault 写入器 — 根据分类结果将内容写入正确的脑区。

支持两种人格模式（通过 PERSONA_MODE 切换）：
- "ENFP" — 能量地图 + 意义锚点 + 本周浮现
- "J" — 今日日志 + 决策日志 + 本周计划（默认模板）
"""
import os
import re
import logging
from pathlib import Path
from datetime import datetime

from .config import (
    VAULT_ROOT, INBOX_DIR, EXEC_DIR, WIKI_DIR,
    INBOX_INSPIRATION, INBOX_CONVERSATION, INBOX_TO_READ, INBOX_TO_PROCESS,
    EXEC_ENERGY, EXEC_EMERGE, EXEC_ANCHOR, EXEC_DECISION, EXEC_DAILY,
    EXEC_TRACKING,
)
from .classifier import Classification, Category

logger = logging.getLogger("friday-brain")

# ===========================================================================
# 人格模式切换 — 改这里改变 exec/ 的写入行为
# ===========================================================================
PERSONA_MODE = "ENFP"  # "ENFP" | "J"


def _timestamp() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


def _datestamp() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def _ensure_file_header(filepath: Path, header: str):
    """确保文件存在并有标题头。"""
    filepath.parent.mkdir(parents=True, exist_ok=True)
    if not filepath.exists():
        filepath.write_text(header + "\n\n", encoding="utf-8")


def route_and_write(classification: Classification, text: str,
                    user_name: str = "用户", source: str = "bot") -> str:
    """根据分类将内容写入 vault，返回给用户的确认消息。"""

    cat = classification.category
    title = classification.title or text[:30]
    ts = _timestamp()

    if cat == Category.QUERY:
        # 查询不写入 vault（由 knowledge 模块处理后可能写入）
        return _format_reply(cat, title, "")

    elif cat == Category.TASK:
        return _write_task(ts, text, title, user_name)

    elif cat == Category.DECISION:
        return _write_decision(ts, text, title, user_name)

    elif cat == Category.INSPIRATION:
        return _write_inspiration(ts, text, title, user_name)

    elif cat == Category.KNOWLEDGE:
        return _write_knowledge(ts, text, title, user_name)

    elif cat == Category.MEETING:
        return _write_meeting(ts, text, title, user_name)

    elif cat == Category.TODO:
        return _write_todo(ts, text, title, user_name)

    elif cat == Category.CHAT:
        return None  # 不存档，不回复确认

    return f"✅ 已记录"


def _format_reply(cat: Category, title: str, detail: str = "") -> str:
    """格式化给用户的确认回复。"""
    replies = {
        Category.TASK: f"📋 记下了，追踪线已更新",
        Category.DECISION: f"🧭 收到，写入意义锚点",
        Category.INSPIRATION: f"💡 灵感已捕获",
        Category.KNOWLEDGE: f"🧠 收到，待提炼",
        Category.MEETING: f"🗣️ 对话已记录",
        Category.TODO: f"📌 已标记",
    }
    return replies.get(cat, f"✅ 已记录")


# ---------------------------------------------------------------------------
# 各分类的写入逻辑
# ---------------------------------------------------------------------------

def _write_task(ts: str, text: str, title: str, user: str) -> str:
    """任务 → exec/追踪线/<标题>.md"""
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    task_file = EXEC_TRACKING / f"{safe_name}.md"

    if task_file.exists():
        entry = f"\n[{ts}] 📱 via {user}\n{text}\n"
        with open(task_file, "a", encoding="utf-8") as f:
            f.write(entry)
        return _format_reply(Category.TASK, title, f"→ 追加到已有追踪线 `追踪线/{safe_name}.md`")

    content = f"""---
created: {_datestamp()}
type: tracking
tags: [追踪线, 自动捕获]
source: {user}
---

# {title}

> 追踪线 — 自动从 IM 对话中捕获

## 进展记录

[{ts}] 📱 via {user}
{text}
"""
    task_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.TASK, title, f"→ 新建追踪线 `追踪线/{safe_name}.md`")


def _write_decision(ts: str, text: str, title: str, user: str) -> str:
    """决策 → 按人格模式写入不同文件"""
    if PERSONA_MODE == "ENFP":
        target = EXEC_ANCHOR
        _ensure_file_header(target,
            "# 意义锚点\n\n"
            "> ENFP 决策记录：不是「为什么选 A 不选 B」，"
            "而是「这件事对我的意义是什么，为什么我愿意投入」。\n"
        )
        entry = (
            f"## [{_datestamp()}] {title}\n\n"
            f"> 来源：{user} · {ts}\n\n"
            f"{text}\n\n"
            f"### 意义追问（Claudian 后续处理）\n"
            f"- 这个选择让我成为什么样的人？\n"
            f"- 如果放弃，我会后悔什么？\n\n"
            f"---\n\n"
        )
    else:
        target = EXEC_DECISION
        _ensure_file_header(target,
            "# 决策日志\n\n"
            "> 记录关键判断：为什么这样做？放弃了哪些选项？\n"
        )
        entry = (
            f"### [{_datestamp()}] {title}\n\n"
            f"- **情境**：{user} · {ts}\n"
            f"- **内容**：{text}\n"
            f"- **判断依据**：（待补充）\n"
            f"- **预期结果**：（待补充）\n"
            f"- **后续验证**：（待补充）\n\n"
            f"---\n\n"
        )

    with open(target, "a", encoding="utf-8") as f:
        f.write(entry)

    return _format_reply(Category.DECISION, title,
                         f"→ `{target.relative_to(VAULT_ROOT)}`")


def _write_inspiration(ts: str, text: str, title: str, user: str) -> str:
    """灵感 → inbox/碎片灵感/"""
    target = INBOX_INSPIRATION
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    insp_file = target / f"{_datestamp()}-{safe_name}.md"

    content = f"""---
created: {_datestamp()}
type: inspiration
source: {user} via bot
---

# {title}

> {ts} · 来自 {user}

{text}

---
*72h 内路由或丢弃 · 由 AI 主动提醒*
"""
    insp_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.INSPIRATION, title)


def _write_knowledge(ts: str, text: str, title: str, user: str) -> str:
    """知识 → inbox/待提炼/"""
    target = INBOX_TO_PROCESS
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    know_file = target / f"{_datestamp()}-{safe_name}.md"

    content = f"""---
created: {_datestamp()}
type: raw-knowledge
source: {user} via bot
---

# {title}

> {ts} · 来自 {user}

{text}

---
## 待提炼

- [ ] 核心观点是什么？
- [ ] 与现有 wiki 的哪些概念有关？
- [ ] 应该升级为实体/概念页面还是合并到已有页面？

*待 Claudian 在 Obsidian 中提炼*
"""
    know_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.KNOWLEDGE, title,
                         f"→ `inbox/待提炼/` · 等你打开 Obsidian 后我会提炼")


def _write_meeting(ts: str, text: str, title: str, user: str) -> str:
    """会议/对话 → inbox/对话记录/"""
    target = INBOX_CONVERSATION
    safe_name = re.sub(r'[\\/:*?"<>|]', '_', title)
    meet_file = target / f"{_datestamp()}-{safe_name}.md"

    content = f"""---
created: {_datestamp()}
type: conversation-log
source: {user} via bot
---

# {title}

> {ts} · 来自 {user}

{text}

---
## 待提炼

- [ ] 关键人物/实体？
- [ ] 核心判断/决定？
- [ ] 可沉淀的知识/方法？
- [ ] 跟进事项？

*待 Claudian 在 Obsidian 中提炼结构化内容*
"""
    meet_file.write_text(content, encoding="utf-8")
    return _format_reply(Category.MEETING, title,
                         f"→ `inbox/对话记录/` · 等你打开 Obsidian 后我会提炼")


def _write_todo(ts: str, text: str, title: str, user: str) -> str:
    """待办 → exec/当前能量区.md 或本周浮现"""
    if PERSONA_MODE == "ENFP":
        target = EXEC_EMERGE
        _ensure_file_header(target,
            "# 本周浮现\n\n"
            "> ENFP 执行记录：不提前计划「今天要做什么」，"
            "而是回顾「这周实际浮现了什么、我推动了什么」。\n\n"
            "## 本周记录\n"
        )
        entry = f"- [{ts}] 📌 {text}\n"
    else:
        target = EXEC_DAILY
        _ensure_file_header(target,
            "# 今日日志\n\n"
            "> 每天只推进 1-2 件关键事。\n\n"
            "## 今日要事\n\n"
            "1. \n2. \n\n"
            "## 今日收束\n\n"
            "- 做了什么：\n- 收获/感悟：\n- 明天要做什么：\n"
        )
        entry = f"- [{ts}] 📌 待办: {text}\n"

    with open(target, "a", encoding="utf-8") as f:
        f.write(entry)

    return _format_reply(Category.TODO, title,
                         f"→ `{target.relative_to(VAULT_ROOT)}`")

"""
知识检索 — 搜索 vault 中的知识并生成回答。

搜索策略：
1. 关键词匹配 wiki/ + skills/
2. Claude 综合回答（如果 API 可用）
"""
import re
import json
import logging
import time
from pathlib import Path

from .config import (
    WIKI_DIR, SKILLS_DIR, VAULT_ROOT,
    LLM_PROVIDER, CLAUDE_API_KEY, CLAUDE_MODEL,
    DEEPSEEK_API_KEY, DEEPSEEK_BASE_URL, DEEPSEEK_MODEL,
    LLM_MAX_TOKENS,
)

logger = logging.getLogger("friday-brain")

# domains 目录
DOMAINS_DIR = VAULT_ROOT / "domains"

# 缓存
_cache = {"pages": {}, "loaded_at": 0}
CACHE_TTL = 300  # 5 分钟


def _load_all_pages():
    """加载 vault 中所有 markdown 页面到缓存。"""
    global _cache
    now = time.time()
    if now - _cache["loaded_at"] < CACHE_TTL and _cache["pages"]:
        return

    pages = {}
    search_dirs = [
        (WIKI_DIR, "wiki"),
        (SKILLS_DIR, "skills"),
        (DOMAINS_DIR, "domains"),
        (VAULT_ROOT / "exec", "exec"),
        (VAULT_ROOT / "inbox", "inbox"),
    ]

    for base_dir, prefix in search_dirs:
        if not base_dir.exists():
            continue
        for md_file in base_dir.rglob("*.md"):
            try:
                content = md_file.read_text(encoding="utf-8")
                # 跳过 frontmatter
                body = content
                if content.startswith("---"):
                    end = content.find("---", 3)
                    if end != -1:
                        body = content[end + 3:].strip()

                # 提取标题
                title = md_file.stem
                for line in content.split("\n"):
                    if line.startswith("# "):
                        title = line.lstrip("# ").strip()
                        break

                key = f"{prefix}/{md_file.relative_to(base_dir)}"
                pages[key] = {
                    "title": title,
                    "path": str(md_file),
                    "content": body,
                }
            except Exception:
                pass

    _cache["pages"] = pages
    _cache["loaded_at"] = now
    logger.info(f"知识库已加载: {len(pages)} 页")


def _extract_search_terms(text: str) -> list:
    """从搜索文本中提取有意义的词段（中文 n-gram + 英文单词）。"""
    import re
    terms = set()

    # 中文：提取 2-5 字片段
    chinese_chars = re.findall(r'[一-鿿]+', text)
    for segment in chinese_chars:
        for length in (4, 3, 2, 5):
            for i in range(len(segment) - length + 1):
                terms.add(segment[i:i + length])

    # 英文/数字：2 字符以上的单词
    english_words = re.findall(r'[a-z0-9]{2,}', text)
    terms.update(english_words)

    return list(terms)


def search(query: str, max_results: int = 5) -> list:
    """关键词搜索，返回相关页面列表。支持中文 n-gram 匹配。"""
    _load_all_pages()

    query_lower = query.lower()
    terms = _extract_search_terms(query_lower)
    scored = []

    for key, page in _cache["pages"].items():
        # 跳过 inbox 备份和日志文件
        if "requests" in key.lower() or "bot.log" in key.lower():
            continue
        score = 0
        title_lower = page["title"].lower()
        content_lower = page["content"].lower()

        # 完整标题命中：查询中包含页面标题
        if title_lower and title_lower in query_lower:
            score += 60
        # 完整查询命中：标题中包含查询关键词
        elif query_lower in title_lower:
            score += 40
        # 词段匹配
        else:
            for term in terms:
                if term in title_lower:
                    score += 15
                if term in content_lower:
                    score += 2

        if score > 0:
            scored.append((score, page))

    scored.sort(key=lambda x: -x[0])
    return [p for _, p in scored[:max_results]]


def _get_llm_api_key() -> str | None:
    """获取当前 LLM 提供商的 API Key。claudian 不需要 Key。"""
    if LLM_PROVIDER == "claudian":
        return "local"  # 非空标记，触发 LLM 路径
    if LLM_PROVIDER == "deepseek" and DEEPSEEK_API_KEY:
        return DEEPSEEK_API_KEY
    if LLM_PROVIDER == "claude" and CLAUDE_API_KEY:
        return CLAUDE_API_KEY
    return None


def answer_query(query: str, user_name: str = "用户") -> str:
    """回答用户查询。有 API Key 就用 LLM 综合回答，否则用关键词摘要。"""
    results = search(query)

    if not results:
        return (
            f"未找到「{query[:30]}」相关内容。\n"
            f"已记录，开 Obsidian 后帮你查。"
        )

    # 构建知识上下文——从匹配页面中提取最相关的段落
    context_parts = []
    for page in results[:3]:
        body = page["content"]
        if body.startswith("---"):
            end = body.find("---", 3)
            if end != -1:
                body = body[end + 3:]
        # 找查询关键词在正文中的位置，取前后 400 字
        best_snippet = body[:600].strip()
        terms = _extract_search_terms(query)
        for term in terms:
            idx = body.lower().find(term.lower())
            if idx > 0:
                start = max(0, idx - 200)
                end_snippet = min(len(body), idx + 400)
                best_snippet = body[start:end_snippet].strip()
                break
        context_parts.append(f"## {page['title']}\n{best_snippet}")

    context = "\n\n".join(context_parts)

    # 如果 LLM API 可用，用它综合回答
    api_key = _get_llm_api_key()
    if api_key:
        try:
            return _llm_answer(query, context, api_key)
        except Exception as e:
            logger.warning(f"LLM 回答失败，回退关键词: {e}")

    # 回退：关键词摘要
    best = results[0]
    title = best["title"]
    body = best["content"]
    if body.startswith("---"):
        end = body.find("---", 3)
        if end != -1:
            body = body[end + 3:]
    lines = body.strip().split("\n")
    summary_parts = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#") or line.startswith("> ") or \
           line.startswith("|") or line.startswith("-"):
            continue
        clean = line.replace("**", "").replace("`", "").replace("__", "")
        summary_parts.append(clean)
        if len("".join(summary_parts)) > 120:
            break
    summary = "".join(summary_parts)[:150]

    return (
        f"📄 {title}\n"
        f"{summary}...\n\n"
        f"开 Obsidian 查看完整内容 → [[{title}]]"
    )


def _llm_answer(query: str, context: str, api_key: str) -> str:
    """使用 LLM API 基于知识库上下文综合回答。"""
    prompt = f"""你是 Friday，Owen 的私人智脑。Owen 是 ENFP，你是 ISTJ 风格——你弥补他的盲点，而不是放大他的倾向。

## 你的风格（ISTJ — 稳、准、不啰嗦）
- Owen 想法多，你需要帮他**聚焦**：从一堆可能性里挑出最关键的 1-2 点
- Owen 容易忘，你需要帮他**记住**：给出明确的事实、数字、结论
- 回复短而结构化，像执行摘要，不像聊天
- 数字用 <b>粗体</b>，多条信息换行拆分
- 不知道就说不知道，诚实比聪明重要

## 知识库
{context}

## Owen
{query}

直接回答。不要任何开场白。"""

    if LLM_PROVIDER == "claudian":
        return _claudian_answer(query, context)
    elif LLM_PROVIDER == "deepseek":
        return _deepseek_answer(prompt, api_key)
    else:
        return _claude_answer(prompt, api_key)


def _deepseek_answer(prompt: str, api_key: str) -> str:
    """使用 DeepSeek API 回答。"""
    from openai import OpenAI

    client = OpenAI(api_key=api_key, base_url=DEEPSEEK_BASE_URL)
    response = client.chat.completions.create(
        model=DEEPSEEK_MODEL,
        messages=[{"role": "user", "content": prompt}],
        max_tokens=LLM_MAX_TOKENS,
    )
    answer = response.choices[0].message.content.strip()
    return f"🤖 {answer}\n\n💡 开 Obsidian 看完整内容"


def _claudian_answer(query: str, context: str) -> str:
    """使用本地 Claude Code CLI 回答。"""
    import subprocess

    prompt = (
        f"你是 Friday 智脑助手。基于 vault 中的知识回答用户问题。\n\n"
        f"Vault 搜索结果：\n{context}\n\n"
        f"用户问题：{query}\n\n"
        f"要求：基于 vault 内容回答，不知道就说不知道。用中文，150 字以内。"
        f"用飞书支持的富文本格式：\n"
        f"- 关键数字用 <b>数字</b> 加粗\n"
        f"- 直接回答，不要开场白"
    )

    try:
        result = subprocess.run(
            ["claude", "-p", prompt],
            capture_output=True, text=True, timeout=60,
            cwd=str(VAULT_ROOT),
        )
        if result.returncode == 0 and result.stdout.strip():
            return result.stdout.strip()
        logger.error(f"Claude CLI 失败: {result.stderr[:200]}")
    except FileNotFoundError:
        logger.error("claude CLI 未找到，请确认 Claude Code 已安装且 claude 命令可用")
    except subprocess.TimeoutExpired:
        logger.error("Claude CLI 超时")
    except Exception as e:
        logger.error(f"Claude CLI 异常: {e}")

    return f"⚠️ Claudian 暂时不可用（Claude Code 可能没开着）"

