def _extract_search_terms(text: str) -> list:
    """从搜索文本中提取有意义的词段（中文 n-gram + 英文单词）。"""
    import re
    terms = set()

    # 中文：提取 2-5 字片段
    chinese_chars = re.findall(r'[一-鿿]+', text)
    for segment in chinese_chars:
        for length in (4, 3, 2, 5):
            for i in range(len(segment) - length + 1):
                terms.add(segment[i:i + length])

    # 英文/数字：2 字符以上的单词
    english_words = re.findall(r'[a-z0-9]{2,}', text)
    terms.update(english_words)

    return list(terms)


def search(query: str, max_results: int = 5) -> list:
    """关键词搜索，返回相关页面列表。支持中文 n-gram 匹配。"""
    _load_all_pages()

    query_lower = query.lower()
    terms = _extract_search_terms(query_lower)
    scored = []

    for key, page in _cache["pages"].items():
        # 跳过 inbox 备份和日志文件
        if "requests" in key.lower() or "bot.log" in key.lower():
            continue
        score = 0
        title_lower = page["title"].lower()
        content_lower = page["content"].lower()

        # 实体页面加权
        if "wiki/实体" in key.lower():
            score += 10

        # 完整标题命中：查询中包含页面标题
        if title_lower and title_lower in query_lower:
            score += 60
        # 完整查询命中：标题中包含查询关键词
        elif query_lower in title_lower:
            score += 40
        # 词段匹配
        else:
            for term in terms:
                if term in title_lower:
                    score += 15
                if term in content_lower:
                    score += 2

        if score > 0:
            scored.append((score, page))

    scored.sort(key=lambda x: -x[0])
    return [p for _, p in scored[:max_results]]


def _get_llm_api_key() -> str | None:
    """获取当前 LLM 提供商的 API Key。claudian 不需要 Key。"""
    if LLM_PROVIDER == "claudian":
        return "local"  # 非空标记，触发 LLM 路径
    if LLM_PROVIDER == "deepseek" and DEEPSEEK_API_KEY:
        return DEEPSEEK_API_KEY
    if LLM_PROVIDER == "claude" and CLAUDE_API_KEY:
        return CLAUDE_API_KEY
    return None


def _is_fact_query(query: str) -> bool:
    """判断是否是事实类查询（数字、具体信息）——这类不走 LLM。"""
    fact_patterns = [
        r"(多少|几个|几|什么|哪些|哪个|谁|什么时候)",
        r"(人数|员工|人员|金额|收入|利润|占比|比例)",
    ]
    return any(re.search(p, query) for p in fact_patterns)


def _find_fact_line(content: str, terms: list) -> str | None:
    """从页面内容中找到最匹配查询的事实行。"""
    lines = content.split("\n")
    for line in lines:
        line_lower = line.lower()
        # 找同时包含多个查询词的行
        matches = [t for t in terms if t in line_lower]
        if len(matches) >= 2:
            return line.strip().lstrip("|").strip()
    # 回退：找包含任意查询词的表格行或文本行
    for line in lines:
        line_lower = line.lower()
        if any(t in line_lower for t in terms):
            stripped = line.strip()
            if ":" in stripped or "|" in stripped or "人" in stripped:
                return stripped.lstrip("|").strip()
    return None


def answer_query(query: str, user_name: str = "用户") -> str:
    """回答用户查询。事实类直接搜原文，理解类走 LLM。"""
    results = search(query)

    if not results:
        return f"知识库中暂无「{query[:30]}」的相关数据。"

    terms = _extract_search_terms(query)

    # 事实类查询：直接找原文行
    if _is_fact_query(query):
        for page in results[:3]:
            fact = _find_fact_line(page["content"], terms)
            if fact:
                return fact

        # 事实行没找到，回退到简短原文
        for page in results[:2]:
            body = page["content"]
            if body.startswith("---"):
                end = body.find("---", 3)
                if end != -1:
                    body = body[end + 3:]
            # 找关键词区域
            for term in terms:
                idx = body.lower().find(term.lower())
                if idx > 0:
                    start = max(0, idx - 100)
                    end = min(len(body), idx + 300)
                    return body[start:end].strip()[:400]
        return f"未找到「{query[:30]}」的明确数据。开 Obsidian 查。"

    # 理解类查询：走 LLM
    context_parts = []
    for page in results[:2]:
        body = page["content"]
        if body.startswith("---"):
            end = body.find("---", 3)
            if end != -1:
                body = body[end + 3:]
        context_parts.append(f"## {page['title']}\n{body[:2000].strip()}")

    context = "\n\n".join(context_parts)

    api_key = _get_llm_api_key()
    if api_key:
        try:
            return _llm_answer(query, context, api_key)
        except Exception as e:
            logger.warning(f"LLM 回答失败: {e}")

    return f"未找到明确答案。开 Obsidian 查完整数据。"


def _llm_answer(query: str, context: str, api_key: str) -> str:
    """使用 LLM API 基于知识库上下文综合回答。"""
    prompt = f"""你是 Friday，Owen 的私人智脑。基于知识库内容回答用户问题。

知识库内容：
---
{context}
---

用户问题：{query}

要求：基于知识库内容回答，不知道就说不知道。用中文，简洁，200 字以内。尽量引用原文数字。"""

    if LLM_PROVIDER == "claudian":
        return _claudian_answer(query, context)
    elif LLM_PROVIDER == "deepseek":
        return _deepseek_answer(prompt, api_key)
    else:
        return _claude_answer(prompt, api_key)


def _deepseek_answer(prompt: str, api_key: str) -> str:
    """使用 DeepSeek API 回答。"""
    from openai import OpenAI

    client = OpenAI(api_key=api_key, base_url=DEEPSEEK_BASE_URL)
    response = client.chat.completions.create(
        model=DEEPSEEK_MODEL,
        messages=[{"role": "user", "content": prompt}],
        max_tokens=LLM_MAX_TOKENS,
    )
    answer = response.choices[0].message.content.strip()
    return f"🤖 {answer}\n\n💡 开 Obsidian 看完整内容"


